  (4, 'multiple_choice', '''Is Anna working today?'' ''No, she ___.''', array['isn''t', 'doesn''t', 'not']::text[], 'isn''t', array[]::text[], 'Вопрос с is → ответ No, she isn''t.'),
  (5, 'multiple_choice', 'Where ___ going?', array['are they', 'they are', 'do they']::text[], 'are they', array[]::text[], 'Where are they going?'),
