  (7, 'multiple_choice', '''Are you using this monitor?'' ''Yes, I ___.''', array['am', 'do', '''m']::text[], 'am', array[]::text[], 'Yes, I am — без сокращения.'),
  (8, 'multiple_choice', 'What ___ on right now?', array['are you working', 'you are working', 'do you working']::text[], 'are you working', array[]::text[], 'What are you working on? — are перед you, глагол с -ing.')
) as v(position, exercise_type, prompt, options, correct_answer, accepted_answers, explanation)
join grammar_topics t on t.unit = 4
