from (values
  (1, 'multiple_choice', 'I ___ like long meetings.', array['don''t', 'doesn''t', 'not']::text[], 'don''t', array[]::text[], 'I → don''t.'),
  (2, 'multiple_choice', 'He ___ work on Fridays.', array['don''t', 'doesn''t', 'isn''t']::text[], 'doesn''t', array[]::text[], 'He → doesn''t + глагол.'),
  (3, 'multiple_choice', 'She doesn''t ___ Python.', array['know', 'knows', 'knowing']::text[], 'know', array[]::text[], 'После doesn''t глагол без -s.'),
  (4, 'fill_blank', 'This function ___ anything. (return, отрицание)', null::text[], 'doesn''t return', array['does not return']::text[], 'It → doesn''t return (без -s).'),
  (5, 'fill_blank', 'We ___ on weekends. (work, отрицание)', null::text[], 'don''t work', array['do not work']::text[], 'We → don''t work.'),
  (6, 'fill_blank', 'My laptop ___ a camera. (have, отрицание)', null::text[], 'doesn''t have', array['does not have']::text[], 'It → doesn''t have (не doesn''t has).'),
  (7, 'multiple_choice', 'The tests ___ on my machine.', array['don''t pass', 'doesn''t pass', 'not pass']::text[], 'don''t pass', array[]::text[], 'The tests = they → don''t pass.'),
  (8, 'multiple_choice', 'Paul ___ coffee.', array['doesn''t drink', 'don''t drink', 'doesn''t drinks']::text[], 'doesn''t drink', array[]::text[], 'Paul = he → doesn''t drink, глагол без -s.')
) as v(position, exercise_type, prompt, options, correct_answer, accepted_answers, explanation)
join grammar_topics t on t.unit = 6
on conflict (topic_id, position) do update set exercise_type = excluded.exercise_type, prompt = excluded.prompt, options = excluded.options, correct_answer = excluded.correct_answer, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;

