insert into grammar_exercises (topic_id, position, exercise_type, prompt, options, correct_answer, accepted_answers, explanation)
select t.id, v.position, v.exercise_type::exercise_type, v.prompt, v.options, v.correct_answer, v.accepted_answers, v.explanation
from (values
  (1, 'multiple_choice', 'Be quiet! The team lead ___ on the phone.', array['talks', 'is talking', 'talk']::text[], 'is talking', array[]::text[], 'Прямо сейчас → present continuous.'),
  (2, 'multiple_choice', 'She usually ___ work at 8 a.m.', array['starts', 'is starting', 'start']::text[], 'starts', array[]::text[], 'usually — привычка → present simple, she → starts.'),
  (3, 'multiple_choice', 'I ___ what you mean.', array['understand', 'am understanding', 'understanding']::text[], 'understand', array[]::text[], 'understand не ставят в continuous.'),
  (4, 'multiple_choice', 'Look! Somebody ___ our demo right now.', array['watches', 'is watching', 'watch']::text[], 'is watching', array[]::text[], 'Look! / right now → present continuous.'),
  (5, 'multiple_choice', 'We ___ a release every two weeks.', array['do', 'are doing', 'does']::text[], 'do', array[]::text[], 'every two weeks — регулярно → present simple.'),
  (6, 'multiple_choice', '___ this word?', array['Do you know', 'Are you knowing', 'You know']::text[], 'Do you know', array[]::text[], 'know не бывает в continuous; вопрос — с do.'),
  (7, 'multiple_choice', 'Right now I ___ on the login page.', array['work', 'am working', 'works']::text[], 'am working', array[]::text[], 'Right now → I am (I''m) working.'),
  (8, 'multiple_choice', 'He ___ tea; he prefers coffee.', array['doesn''t like', 'isn''t liking', 'don''t like']::text[], 'doesn''t like', array[]::text[], 'like — глагол состояния → present simple, he → doesn''t.')
) as v(position, exercise_type, prompt, options, correct_answer, accepted_answers, explanation)
join grammar_topics t on t.unit = 8
on conflict (topic_id, position) do update set exercise_type = excluded.exercise_type, prompt = excluded.prompt, options = excluded.options, correct_answer = excluded.correct_answer, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;

